-- Morning care research foundation. Apply after SQL 23/26/31.
-- Filename generated by Supabase CLI migration new (2.81.3).
-- Private research only: no public table, RPC, API exposure or existing row changes.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

CREATE SCHEMA care_research;
REVOKE ALL ON SCHEMA care_research FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SCHEMA care_research TO service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA care_research REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA care_research REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC, anon, authenticated;

CREATE TABLE care_research.ingestion_batches (
    batch_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    dataset_key TEXT NOT NULL CHECK (dataset_key ~ '^[a-z0-9][a-z0-9_-]{0,99}$'),
    payload_sha256 TEXT NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
    sample_sha256 TEXT NOT NULL CHECK (sample_sha256 ~ '^[0-9a-f]{64}$'),
    loader_version TEXT NOT NULL,
    checked_on DATE NOT NULL,
    school_count INTEGER NOT NULL CHECK (school_count > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (dataset_key, payload_sha256)
);

CREATE TABLE care_research.care_services (
    service_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    service_type TEXT NOT NULL CHECK (service_type IN ('school_morning_care', 'kium_morning_care', 'walking_school_bus')),
    school_id TEXT REFERENCES public.school_master(school_id) ON DELETE RESTRICT,
    center_id TEXT REFERENCES public.care_centers(center_id) ON DELETE RESTRICT,
    provider_external_id TEXT,
    district TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (
        (service_type = 'school_morning_care' AND school_id IS NOT NULL AND center_id IS NULL)
        OR (service_type = 'kium_morning_care' AND school_id IS NULL AND (center_id IS NOT NULL OR provider_external_id IS NOT NULL))
        OR (service_type = 'walking_school_bus' AND school_id IS NULL AND center_id IS NULL AND provider_external_id IS NOT NULL)
    ),
    UNIQUE (service_type, school_id)
);
CREATE INDEX care_services_school_idx ON care_research.care_services (school_id) WHERE school_id IS NOT NULL;
CREATE UNIQUE INDEX care_services_center_idx ON care_research.care_services (service_type, center_id) WHERE center_id IS NOT NULL;
CREATE UNIQUE INDEX care_services_external_idx ON care_research.care_services (service_type, provider_external_id) WHERE provider_external_id IS NOT NULL;

CREATE TABLE care_research.care_service_sources (
    source_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    source_kind TEXT NOT NULL CHECK (source_kind IN ('annual_plan', 'current_notice', 'institution_confirmation', 'policy', 'current_listing')),
    publisher TEXT NOT NULL,
    official_url TEXT NOT NULL CHECK (official_url ~ '^https?://'),
    document_name TEXT NOT NULL,
    raw_sha256 TEXT NOT NULL CHECK (raw_sha256 ~ '^[0-9a-f]{64}$'),
    text_sha256 TEXT NOT NULL CHECK (text_sha256 ~ '^[0-9a-f]{64}$'),
    text_lines INTEGER NOT NULL CHECK (text_lines > 0),
    published_on DATE,
    source_list_checked_at TIMESTAMPTZ,
    source_live_rechecked_on DATE,
    checked_on DATE NOT NULL,
    parser_version TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (official_url, raw_sha256, text_sha256)
);

CREATE TABLE care_research.care_service_observations (
    observation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    batch_id UUID NOT NULL REFERENCES care_research.ingestion_batches(batch_id) ON DELETE RESTRICT,
    service_id UUID NOT NULL REFERENCES care_research.care_services(service_id) ON DELETE RESTRICT,
    academic_year INTEGER CHECK (academic_year BETWEEN 2000 AND 2100),
    service_calendar_year INTEGER CHECK (service_calendar_year BETWEEN 2000 AND 2100),
    calendar_scope TEXT NOT NULL CHECK (calendar_scope IN ('term_weekday', 'vacation', 'school_holiday', 'specific_dates')),
    valid_from DATE,
    valid_to DATE,
    operation_status TEXT NOT NULL DEFAULT 'unknown' CHECK (operation_status IN ('confirmed_operating', 'confirmed_not_operating', 'unknown')),
    plan_status TEXT NOT NULL CHECK (plan_status IN ('planned', 'conditional', 'not_found', 'not_planned')),
    verification_basis TEXT NOT NULL CHECK (verification_basis IN ('annual_plan', 'current_notice', 'institution_confirmation', 'policy', 'current_listing')),
    operation_source_id UUID REFERENCES care_research.care_service_sources(source_id) ON DELETE RESTRICT,
    admission_status TEXT NOT NULL DEFAULT 'unknown' CHECK (admission_status IN ('accepting', 'closed', 'waitlist', 'unknown')),
    eligibility_text TEXT,
    application_window TEXT,
    escort_status TEXT NOT NULL DEFAULT 'unknown' CHECK (escort_status IN ('confirmed_available', 'confirmed_unavailable', 'unknown')),
    escort_source_id UUID REFERENCES care_research.care_service_sources(source_id) ON DELETE RESTRICT,
    checked_on DATE NOT NULL,
    review_state TEXT NOT NULL CHECK (review_state IN ('candidate', 'assistant_source_text_review', 'institution_confirmed')),
    publication_state TEXT NOT NULL DEFAULT 'research_only' CHECK (publication_state = 'research_only'),
    supersedes_id UUID REFERENCES care_research.care_service_observations(observation_id) ON DELETE RESTRICT,
    note TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (num_nonnulls(academic_year, service_calendar_year) = 1),
    CHECK (valid_from IS NULL OR valid_to IS NULL OR valid_from <= valid_to),
    CHECK (verification_basis <> 'annual_plan' OR operation_status = 'unknown'),
    CHECK (operation_status = 'unknown' OR (valid_from IS NOT NULL AND valid_to IS NOT NULL AND operation_source_id IS NOT NULL AND verification_basis IN ('current_notice', 'institution_confirmation'))),
    CHECK (escort_status = 'unknown' OR (escort_source_id IS NOT NULL AND valid_from IS NOT NULL AND valid_to IS NOT NULL)),
    UNIQUE NULLS NOT DISTINCT (batch_id, service_id, academic_year, service_calendar_year, calendar_scope)
);
CREATE INDEX care_observations_service_year_idx ON care_research.care_service_observations (service_id, academic_year, checked_on DESC);
CREATE INDEX care_observations_operation_source_idx ON care_research.care_service_observations (operation_source_id) WHERE operation_source_id IS NOT NULL;
CREATE INDEX care_observations_escort_source_idx ON care_research.care_service_observations (escort_source_id) WHERE escort_source_id IS NOT NULL;
CREATE INDEX care_observations_supersedes_idx ON care_research.care_service_observations (supersedes_id) WHERE supersedes_id IS NOT NULL;

CREATE TABLE care_research.care_service_schedules (
    schedule_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    observation_id UUID NOT NULL REFERENCES care_research.care_service_observations(observation_id) ON DELETE RESTRICT,
    segment_key TEXT NOT NULL,
    target_grades SMALLINT[] CHECK (target_grades IS NULL OR (cardinality(target_grades) > 0 AND target_grades <@ ARRAY[1,2,3,4,5,6]::SMALLINT[] AND array_position(target_grades, NULL) IS NULL)),
    weekdays SMALLINT[] CHECK (weekdays IS NULL OR (cardinality(weekdays) > 0 AND weekdays <@ ARRAY[1,2,3,4,5,6,7]::SMALLINT[] AND array_position(weekdays, NULL) IS NULL)),
    start_time TIME,
    end_time TIME,
    end_boundary TEXT,
    time_status TEXT NOT NULL CHECK (time_status IN ('stated', 'open_end', 'source_conflict', 'not_found')),
    start_time_candidates TEXT[],
    capacity INTEGER CHECK (capacity > 0),
    capacity_qualifier TEXT,
    CHECK (start_time IS NULL OR start_time < time '24:00'),
    CHECK (end_time IS NULL OR end_time < time '24:00'),
    CHECK (start_time IS NULL OR end_time IS NULL OR start_time < end_time),
    CHECK (time_status <> 'stated' OR (start_time IS NOT NULL AND end_time IS NOT NULL)),
    CHECK (time_status <> 'open_end' OR (start_time IS NOT NULL AND end_time IS NULL AND end_boundary IS NOT NULL)),
    CHECK (time_status <> 'source_conflict' OR start_time IS NULL OR end_time IS NULL),
    CHECK (time_status <> 'not_found' OR (start_time IS NULL AND end_time IS NULL AND target_grades IS NULL AND capacity IS NULL)),
    UNIQUE (observation_id, segment_key),
    UNIQUE (schedule_id, observation_id)
);

CREATE TABLE care_research.observation_sources (
    observation_id UUID NOT NULL REFERENCES care_research.care_service_observations(observation_id) ON DELETE RESTRICT,
    source_id UUID NOT NULL REFERENCES care_research.care_service_sources(source_id) ON DELETE RESTRICT,
    PRIMARY KEY (observation_id, source_id)
);
CREATE INDEX observation_sources_source_idx ON care_research.observation_sources (source_id);

CREATE TABLE care_research.care_service_assertions (
    assertion_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    observation_id UUID NOT NULL,
    schedule_id UUID,
    source_id UUID NOT NULL,
    field_name TEXT NOT NULL CHECK (field_name IN ('start_time', 'end_time', 'target_grades', 'eligibility_text', 'application_window', 'capacity', 'plan_status', 'time_status', 'operation_status', 'escort_status')),
    value JSONB NOT NULL CHECK (value <> 'null'::JSONB),
    evidence_key TEXT NOT NULL,
    line_start INTEGER NOT NULL CHECK (line_start > 0),
    line_end INTEGER NOT NULL CHECK (line_end >= line_start),
    evidence_excerpt TEXT NOT NULL CHECK (length(evidence_excerpt) > 0),
    extraction_method TEXT NOT NULL,
    FOREIGN KEY (observation_id, source_id) REFERENCES care_research.observation_sources(observation_id, source_id) ON DELETE RESTRICT,
    FOREIGN KEY (schedule_id, observation_id) REFERENCES care_research.care_service_schedules(schedule_id, observation_id) ON DELETE RESTRICT,
    UNIQUE (observation_id, field_name, evidence_key)
);
CREATE INDEX care_assertions_source_idx ON care_research.care_service_assertions (source_id);
CREATE INDEX care_assertions_schedule_idx ON care_research.care_service_assertions (schedule_id, observation_id) WHERE schedule_id IS NOT NULL;

CREATE TABLE care_research.school_service_links (
    link_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    service_id UUID NOT NULL REFERENCES care_research.care_services(service_id) ON DELETE RESTRICT,
    school_id TEXT NOT NULL REFERENCES public.school_master(school_id) ON DELETE RESTRICT,
    source_id UUID NOT NULL REFERENCES care_research.care_service_sources(source_id) ON DELETE RESTRICT,
    academic_year INTEGER NOT NULL CHECK (academic_year BETWEEN 2000 AND 2100),
    valid_from DATE,
    valid_to DATE,
    route_key TEXT NOT NULL,
    boarding_point TEXT,
    handoff_location TEXT,
    pickup_time TIME,
    target_grades SMALLINT[] CHECK (target_grades IS NULL OR (cardinality(target_grades) > 0 AND target_grades <@ ARRAY[1,2,3,4,5,6]::SMALLINT[] AND array_position(target_grades, NULL) IS NULL)),
    weekdays SMALLINT[] CHECK (weekdays IS NULL OR (cardinality(weekdays) > 0 AND weekdays <@ ARRAY[1,2,3,4,5,6,7]::SMALLINT[] AND array_position(weekdays, NULL) IS NULL)),
    escort_status TEXT NOT NULL DEFAULT 'unknown' CHECK (escort_status IN ('confirmed_available', 'confirmed_unavailable', 'unknown')),
    link_status TEXT NOT NULL CHECK (link_status IN ('candidate', 'explicit_source')),
    CHECK (valid_from IS NULL OR valid_to IS NULL OR valid_from <= valid_to),
    CHECK (escort_status = 'unknown' OR (link_status = 'explicit_source' AND valid_from IS NOT NULL AND valid_to IS NOT NULL)),
    UNIQUE (service_id, school_id, academic_year, route_key, source_id)
);
CREATE INDEX school_service_links_school_idx ON care_research.school_service_links (school_id, academic_year);
CREATE INDEX school_service_links_source_idx ON care_research.school_service_links (source_id);

-- Deny browser roles even if the schema is accidentally exposed later.
-- No policies is intentional: the server service role bypasses RLS, browser roles cannot use the schema.
ALTER TABLE care_research.ingestion_batches ENABLE ROW LEVEL SECURITY;
ALTER TABLE care_research.care_services ENABLE ROW LEVEL SECURITY;
ALTER TABLE care_research.care_service_sources ENABLE ROW LEVEL SECURITY;
ALTER TABLE care_research.care_service_observations ENABLE ROW LEVEL SECURITY;
ALTER TABLE care_research.care_service_schedules ENABLE ROW LEVEL SECURITY;
ALTER TABLE care_research.observation_sources ENABLE ROW LEVEL SECURITY;
ALTER TABLE care_research.care_service_assertions ENABLE ROW LEVEL SECURITY;
ALTER TABLE care_research.school_service_links ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA care_research FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT ON ALL TABLES IN SCHEMA care_research TO service_role;

COMMENT ON SCHEMA care_research IS 'Private append-only morning-care research; not a public serving API. Annual plans never confirm live operation.';
COMMENT ON TABLE care_research.ingestion_batches IS 'Idempotent immutable payload batches; changed payload creates a new batch and preserves history.';
COMMENT ON TABLE care_research.care_service_assertions IS 'Per-field source evidence, scoped to an observation and optionally one schedule.';
COMMIT;
